    # Operations on contacts batch.
    class ContactsBatch < Base
      # Read contacts in bulk.
      #
      # BillionSend extension: returns up to 1000 contacts by id or by email address in one request,
      # in request order, optionally with their properties and topic subscriptions. Entries that
      # match no contact are listed under `missing` instead of failing the call. One call counts as
      # one request against the rate limit.
      #
      # +POST /contacts/batch/get+
      #
      # @return [Hash] the parsed JSON answer
      def get(params, extra_headers: nil, timeout: nil)
        @client.request(
          "POST",
          "/contacts/batch/get",
          body: params,
          extra_headers: extra_headers,
          timeout: timeout
        )
      end

      # Delete contacts in bulk.
      #
      # Deletes up to 1000 contacts by id or by email address in one request and lists the rows
      # actually deleted; unknown ids or addresses are skipped. Emails stay in the log; `erase:
      # true` also scrubs each address from email history, event payloads and API logs, like DELETE
      # /contacts/{id}?erase=true.
      #
      # +POST /contacts/batch/remove+
      #
      # @return [Hash] the parsed JSON answer
      def remove(params, extra_headers: nil, timeout: nil)
        @client.request(
          "POST",
          "/contacts/batch/remove",
          body: params,
          extra_headers: extra_headers,
          timeout: timeout
        )
      end

      # Create contacts in bulk.
      #
      # Creates up to 1000 contacts in one request. Each item is a CreateContactRequest.
      # `on_conflict` decides what happens to an email that already belongs to a contact — `error`
      # (default), `skip`, or `upsert`. An upsert updates `first_name`/`last_name` only when
      # provided, merges `properties` (provided keys overwrite), adds `segments` and upserts
      # `topics`. `unsubscribed: true` opts the contact out; `unsubscribed: false` on an already
      # unsubscribed contact is ignored — a batch never re-subscribes anyone, that stays an explicit
      # PATCH /contacts/{id}. The `x-batch-validation` header picks strict (default, all-or-nothing)
      # or permissive (valid subset written, failures listed in `errors`).
      #
      # +POST /contacts/batch+
      #
      # @return [Hash] the parsed JSON answer
      def create(params, on_conflict: nil, batch_validation: nil, extra_headers: nil, timeout: nil)
        @client.request(
          "POST",
          "/contacts/batch",
          query: { "on_conflict" => on_conflict },
          headers: { "x-batch-validation" => batch_validation },
          body: params,
          extra_headers: extra_headers,
          timeout: timeout
        )
      end
    end

