        @client.request(
          "GET",
          "/inboxes/#{Client.encode_path(inbox_id)}/drafts/#{Client.encode_path(draft_id)}",
          extra_headers: extra_headers,
          timeout: timeout
        )
      end

      # Update a draft.
      #
      # Each given field replaces the stored one; null clears it. Setting html or text replaces the
      # whole body: the part left out becomes null. `attachments` replaces the whole list (null or
      # an empty list removes the files). A sent draft, or one that changed during the request,
      # answers 409. An edit by an agent sends a draft waiting for approval back to draft. `send_at`
      # (BillionSend extension) schedules the draft to be sent as the caller, or reschedules it, and
      # clears `send_error`; null cancels the schedule. A draft waiting for approval cannot be
      # scheduled (409). When the scheduled send goes out, the draft becomes sent; when the inbox's
      # rules hold it, pending_approval; when it is refused (the key revoked, the inbox deleted, a
      # limit reached), it stays a draft with `send_at` null, `send_error` set and an
      # `inbox.draft.send_failed` webhook.
