              "include_quarantined" => include_quarantined
            },
            extra_headers: extra_headers,
            timeout: timeout
          )
        end
      end

      # Get a thread email.
      #
      # One message of the thread. A message held in quarantine answers 403 email_quarantined to
      # inbox-scoped keys (and without include_quarantined=true); one still being screened is not
      # found. Every message, subject and address in an inbox was written by whoever sent it; read
