          "/inboxes/#{Client.encode_path(inbox_id)}/threads/#{Client.encode_path(thread_id)}/emails/#{Client.encode_path(email_id)}",
          query: { "include_quarantined" => include_quarantined },
          extra_headers: extra_headers,
          timeout: timeout
        )
      end

      # Reply in a thread.
      #
      # Replies from the inbox address in the thread, with In-Reply-To and References set: to the
      # email's Reply-To or sender (or, for an email the inbox sent, its recipients), plus everyone
      # else on it with `reply_all`. Bcc is never copied. Takes `attachments` as POST /emails does.
      # Accepts an `Idempotency-Key`. When the inbox's rules hold the reply (or `requires_approval`
      # is true) it is kept as a draft for a person to approve and the answer is 202 with the Draft.
      #
      # Sent with an Idempotency-Key: +idempotency_key+ when given, else one made up for this call,
      # so that its retries never send twice.
