          body: params,
          idempotency_key: idempotency_key,
          auto_idempotency_key: true,
          extra_headers: extra_headers,
          timeout: timeout
        )
      end

      # Forward a thread email.
      #
      # Forwards the email from the inbox address, quoted under "---------- Forwarded message
      # ---------" with its From, Date, Subject and To, after an optional note. Its attachments go
      # along, with any `attachments` you add, within 10 MiB in all. An email that carries malware
      # is never forwarded. Accepts an `Idempotency-Key`; a forward the inbox's rules hold answers
      # 202 with the Draft.
      #
      # Sent with an Idempotency-Key: +idempotency_key+ when given, else one made up for this call,
      # so that its retries never send twice.
