        extra_headers: nil,
        timeout: nil
      )
        @client.request(
          "POST",
          "/inboxes/#{Client.encode_path(inbox_id)}/threads/#{Client.encode_path(thread_id)}/emails/#{Client.encode_path(email_id)}/forward",
          body: params,
          idempotency_key: idempotency_key,
          auto_idempotency_key: true,
          extra_headers: extra_headers,
          timeout: timeout
        )
      end
    end

