        @unsubscribes ||= Unsubscribes.new(self)
      end

      # @return [Resources::Usage]
      def usage
        @usage ||= Usage.new(self)
      end

      # @return [Resources::Verifications]
      def verifications
        @verifications ||= Verifications.new(self)
      end

      # @return [Resources::Webhooks]
      def webhooks
        @webhooks ||= Webhooks.new(self)
      end
    end
  end
end
